import json
from pathlib import Path
extra={
'05-029':'Волнения1648 и1662годов полезно сравнить по механизму кризиса. В первом случае недовольство связывалось с налоговыми решениями и взысканием недоимок, во втором —с обесценением медных денег и недоверием к денежной политике. Общее участие городских групп не делает их требования одинаковыми. Челобитная сообщает, как просители обосновывали претензии перед властью, но не является точным опросом всех участников толпы. Правительственный рассказ может представлять конфликт как нарушение порядка, а позднее повествование выделять наиболее драматичные сцены. Для реконструкции нужно сопоставить решения до выступления, состав требований, ответ властей и последующие изменения. Это позволяет отличить непосредственный повод от накопившихся причин и не считать репрессию единственным последствием кризиса.',
'05-030':'Дипломатический текст1667года заключён представителями Москвы и Речи Посполитой, поэтому его согласованные условия не равны общему согласию казачества или жителей разделённых областей. Нужно отдельно спрашивать, кто участвовал в переговорах, кто исполнял договорённости на местах и какие интересы остались за пределами соглашения. Разделение по Днепру также не уничтожило родственных, хозяйственных и религиозных связей между берегами. Для понимания перемирия полезно сопоставить территориальные статьи с дальнейшими конфликтами вокруг контроля и подданства. Прочность дипломатического компромисса проверяется его исполнением, а не только наличием подписи. Такой анализ объясняет одновременно окончание определённого этапа войны и сохранение нерешённых вопросов, не распространяя позднейший результат назад во времени.',
'05-031':'Историк должен различить решение присутствовавших на раде, последующие присяги и документы о полномочиях гетманской власти. Они отражают несколько стадий и могут показывать несовпадающие ожидания сторон. Юридические понятия меняли смысл, поэтому современное слово «суверенитет» нельзя применять без пояснения того, какие полномочия реально сохранялись и кем признавались. Дальнейшее ограничение автономии не доказывает, что каждый участник1654года заранее представлял этот результат. Одновременно сохранение части институтов не отменяет усиления зависимости от царской власти. Сопоставление переписки, условий переговоров и практики управления позволяет обсуждать отношения предметно: кто назначал должностных лиц, собирал налоги и вёл внешние сношения. Это продуктивнее, чем выбирать политически удобное название вместо изучения механизма.',
'05-032':'При описании издания полезно сравнить титульные сведения, послесловие, особенности набора и сохранившиеся экземпляры. Послесловие может рассказывать о задачах печатника и покровительстве, но его риторика требует такого же критического чтения, как любой другой текст. Не все книги дошли в одинаковой сохранности, поэтому число известных экземпляров не равно первоначальному тиражу. Исправления, пометы владельцев и следы пользования помогают исследовать жизнь книги после выхода из типографии. Передвижения Ивана Фёдорова показывают значение разных заказчиков и местных условий для развития печати. Однако сам факт работы мастера в нескольких центрах не позволяет считать каждую последующую типографию прямым продолжением одного неизменного учреждения или одной политической программы.',
'06-001':'Для сравнения России концаXVIIвека с петровской эпохой нужно выбрать конкретные признаки перемен: численность и устройство войска, порядок сбора денег, подготовку специалистов, состав центральных учреждений. Если заранее объявить всё предшествующее «старым», а всё последующее «новым», преемственность исчезает из объяснения. Приглашение иностранных мастеров и военные преобразования существовали до самостоятельной политики Петра, но при нём изменились масштаб и сочетание мер. Источники центральной власти обычно лучше показывают намерения, чем повседневную работу в далёком уезде. Поэтому указ дополняют отчётом, расходной записью и местной жалобой. Сопоставление позволяет объяснить ускорение преобразований через давление войны и накопленный опыт, не превращая реформы ни в случайную прихоть, ни в заранее неизбежный сценарий.',
'06-002':'Рассказы о детстве будущего реформатора легко строятся как доказательство его заранее известного величия. Но позднейший успех не устанавливает намерений ребёнка и не делает каждую раннюю игру проектом будущей армии. Полезно различать современный событию документ, позднюю запись участника и биографический анекдот. Обучение, круг общения и практика военных упражнений создавали возможности, но дальнейший выбор зависел от политической борьбы и ресурсов. Стрелецкие выступления также нельзя объяснить только личной ненавистью царя: необходимо учитывать службу, платежи и придворные коалиции. Такой подход сохраняет значение индивидуального опыта Петра, одновременно показывая, какие стороны биографии подтверждаются свидетельствами, какие реконструируются и где уверенная психологическая мотивировка источниками не обеспечена.',
'06-003':'Проверяя результаты посольства, стоит разделить заявленную дипломатическую цель, практические договорённости и обучение участников. Неудача в создании нужного союза не означает отсутствия любых приобретённых знаний или специалистов. Напротив, личное знакомство с кораблестроением не доказывает немедленного переноса всей производственной системы в Россию. Для этого требовались материалы, мастера, средства и организация работ. Записки путешественников передают впечатления, но могут преувеличивать необычность увиденного для собственного читателя. Полезно сопоставить их с контрактами о найме, закупками и последующими распоряжениями. Тогда «европейское влияние» становится проверяемой цепочкой конкретных действий, а не объяснением всех последующих реформ одним путешествием. Одновременно заметно, какие внешние образцы были приспособлены к местным задачам.',
'06-004':'Военный устав описывает желаемый порядок, а не одинаковую подготовку каждой части. Для оценки реформ нужны сведения о наборе, обучении, вооружении, снабжении и командных решениях. Число записанных в полк людей может отличаться от числа способных участвовать в походе: влияли болезни, откомандирование и недостаток экипировки. Поэтому рост штата сам по себе ещё не доказывает роста боевой силы. Сравнение ранних неудач с последующими успехами полезно лишь при учёте изменившихся условий, союзников и действий противника. Рекрутская система обеспечивала людей, но перекладывала издержки на семьи и общины. Это позволяет объяснять военное усиление государства вместе с социальными последствиями, не смешивая эффективность армии с благополучием населения.',
'06-005':'Хронология Северной войны не является прямой линией от Нарвы к неизбежной победе. Правительства меняли планы под влиянием снабжения, союзов и действий противника. Крупное сухопутное сражение могло изменить инициативу, но не заменить борьбы за порты, коммуникации и дипломатические условия. Для объяснения длительности войны полезно сравнить ресурсы сторон и то, какие результаты каждая считала достаточными для мира. Военные реляции показывают официальное представление победы; расходные документы и жалобы позволяют увидеть её цену. Историческая карта должна относиться к определённому этапу, поскольку политическая принадлежность областей и фактическое присутствие армий не всегда совпадали. Сопоставление договорного результата с ходом кампаний раскрывает механизм изменения балтийского равновесия без превращения войны в перечень героических эпизодов.',
'06-006':'При сравнении сообщений о Полтавской битве важно установить, что именно подсчитывает автор: участников, наличный состав частей, пленных или потери. Разные категории и время составления могут создавать видимое противоречие чисел. Без надёжной общей методики точность до одного человека будет вводить в заблуждение. Для реконструкции действий полезны реляции, планы местности и сведения о предшествовавшем состоянии армий. Решение КарлаXII и положение его союзников нужно исследовать в условиях конкретного похода, а не объяснять результат только личной смелостью или ошибкой монарха. Победа усилила положение России, однако продолжение войны показывает различие между переломом военного соотношения и окончательным миром. Именно связь этих уровней придаёт сражению историческое значение.',
'06-007':'План города показывает замысел размещения улиц и учреждений, но не гарантирует его немедленного исполнения. Сопоставление планов разных лет, строительных распоряжений и сведений о переселённых людях позволяет увидеть постепенность формирования столицы. Географическое преимущество порта также зависело от транспорта в глубь страны, условий навигации и государственного принуждения к торговле через новый центр. Поэтому основание крепости, появление городского населения и перенос столичных функций рассматривают отдельно. Такая последовательность объясняет, как политическое решение превращалось в действующую городскую среду и какую цену за это платили работники и переселяемые группы.',
'06-008':'Для оценки роста мануфактур нужно сравнивать объём продукции, затраты и правовое положение работников. Увеличение выпуска могло происходить благодаря техническому изменению, расширению числа занятых или усилению повинностей —это разные механизмы. Государственный заказ давал спрос, но мог сопровождаться административными нормами, задержкой платежей и ограничением самостоятельности владельца. Расположение предприятия также зависело от руды, леса, воды и доставки готового товара. Поэтому выражение «рост промышленности» полезно раскрывать через конкретную производственную цепочку, а не использовать как доказательство одинаковой выгоды для казны, владельца и зависимого работника.',
'06-010':'Духовный регламент сообщает о нормативной организации церковной власти, но её повседневная работа нуждается в отдельной проверке. Члены коллегиального учреждения могли спорить, а административное подчинение не уничтожало сразу всех прежних практик. Для исследования полезны постановления Синода, переписка епископов и сведения о приходской жизни. Они показывают разные уровни системы и не должны сводиться к одному указу. Особое значение имеет различие между изменением высшего управления и верованиями населения: упразднение патриаршей формы не означало прекращения православной традиции. Так институциональная реформа рассматривается без смешения государственных целей, канонических оснований и опыта верующих.',
'06-012':'Императорский титул выражал притязание на новое международное положение и закреплял символический итог победы. Но признание титула другими дворами и изменение практических возможностей государства были разными процессами. Для объяснения империи недостаточно назвать дату: нужно исследовать управление разными землями, обязанности подданных и способы включения местных элит. Присутствие множества языков и религий не означало равенства всех групп перед властью. Сопоставление торжественного акта с налоговыми, судебными и административными документами показывает, как имперская идея соединялась с действующими институтами, и позволяет отличить представление монархии о себе от повседневной организации её владений.',
'06-014':'Смена монарха становится понятнее, если составить карту участников: наследники, гвардейские части, придворные группировки и высшие учреждения. Их поддержка могла обеспечиваться обещаниями, прежними связями и ожиданием наград. Однако позднейший успех коалиции не доказывает полного первоначального единства её участников. Источники победителей часто представляют переворот восстановлением законности, а не борьбой интересов. Поэтому полезно сопоставить официальное объявление, сведения о действиях войск и последующие назначения. Такой анализ объясняет, как неясность наследования соединялась с организационной силой близких ко двору групп, не сводя всё столетие к случайному капризу гвардейцев.',
'06-017':'Для оценки екатерининской программы полезно сравнить три слоя: текст Наказа, требования депутатских наказов и реально изданные законы. Между ними могли существовать совпадения и противоречия. Отсутствие полного нового уложения не делает обсуждение бесполезным, но и не превращает его идеи в действующее право. Подобным образом рост городов и внешней торговли не позволяет без дополнительных данных говорить о равном улучшении жизни всех подданных. Вопрос «для кого изменились возможности?» связывает законодательство, хозяйство и сословные отношения. Он помогает объяснить совместное существование культурного покровительства, административного развития и сохранения крепостной зависимости.',
'06-019':'Повстанческий манифест раскрывает публичное обещание и способ обоснования власти Пугачёва, но не доказывает одинаковую программу всех примкнувших групп. Казачьи, крестьянские и местные этнические интересы могли соединяться временно. Правительственное донесение также выражает определённую перспективу: командир объяснял состояние порядка, действия войска и собственные решения. Для реконструкции нужны оба ряда документов, а также сведения о насилии против мирных жителей. Нельзя считать каждого пострадавшего участником одной стороны или оправдывать расправу предшествующим злоупотреблением. Раздельное исследование требований, мобилизации и последствий позволяет понять масштаб движения без идеализации восстания или государственного подавления.'}
base=Path('src/content/lessons')
snapshot={}
for id,t in extra.items():
 p=base/f'{id}.json';d=json.loads(p.read_text());snapshot[id]=d['deep']['text']
 if len(d['deep']['text'].split())<100:
  d['deep']['text']+='\n\n'+t
  assert d['deep']['text'].startswith(snapshot[id])
  p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 assert len(d['deep']['text'].split())>=100,(id,len(d['deep']['text'].split()))
 print(id,len(d['deep']['text'].split()))
p=Path('tasks/001-russian-history-course/eighteenth-deep-before-final.json')
if not p.exists():p.write_text(json.dumps(snapshot,ensure_ascii=False,indent=2)+'\n')
